$$\begin{array}{l}
  {g^{\prime}(x) = \lim\limits_{h\rightarrow 0}\frac{g(x + h) - g(x)}{h} = \lim\limits_{h\rightarrow 0}\frac{cf(x + h) - cf(x)}{h}} \\
  {\phantom{g^{\prime}(x)} = c\lim\limits_{h\rightarrow 0}\frac{f(x + h) - f(x)}{h}} \\
  {\phantom{g^{\prime}(x)} = cf^{\prime}(x)}
  \end{array}$$

$$\begin{array}{l}
  {S^{\prime}(t) = \frac{d}{dt}\left\lbrack \frac{5t}{t^{2} + 1} \right\rbrack = 5\frac{d}{dt}\left\lbrack \frac{t}{t^{2} + 1} \right\rbrack} \\
  {\phantom{S^{\prime}(t)} = 5\left\lbrack \frac{\left( t^{2} + 1 \right)(1) - t(2t)}{\left( t^{2} + 1 \right)^{2}} \right\rbrack} \\
  {\phantom{S^{\prime}(t)} = 5\left\lbrack \frac{t^{2} + 1 - 2t^{2}}{\left( t^{2} + 1 \right)^{2}} \right\rbrack = \frac{5\left( 1 - t^{2} \right)}{\left( t^{2} + 1 \right)^{2}}}
  \end{array}$$

$$\begin{array}{l}
  {C(251) - C(250) = \frac{C(251) - C(250)}{1} \approx \frac{C(250 + h) - C(250)}{h}(h\text{small})} \\
  {\phantom{C(251) - C(250)}{\approx \lim\limits_{h\rightarrow 0}\frac{C(250 + h) - C(250)}{h} = C^{\prime}(250)}}
  \end{array}$$

$$\begin{array}{l}
  {\Delta y = f\left( x + \Delta x \right) - f(x) = f(2.01) - f(2)} \\
  {\phantom{\Delta y} = (2.01)^{3} - 2^{3} = 8.120601 - 8 = 0.120601}
  \end{array}$$

$$\begin{array}{l}
  {\Delta y = f\left( x + \Delta x \right) - f(x) = f(1.98) - f(2)} \\
  {\phantom{\Delta y} = (1.98)^{3} - 2^{3} = 7.762392 - 8 = - 0.237608}
  \end{array}$$

$$\begin{array}{l}
  {\Delta y \approx dy = f^{\prime}(x)\Delta x} \\
  {\phantom{\Delta y \approx dy} = \left( \left. \frac{1}{2\sqrt{x}} \right|_{x = 25} \right) \cdot (1.5) = \left( \frac{1}{10} \right)(1.5) = 0.15}
  \end{array}$$

$$\begin{array}{l}
  {\pi R^{2} - \pi r^{2} = f(R) - f(r)} \\
  {\phantom{\pi R^{2} - \pi r^{2}} = \Delta A\qquad\begin{array}{l}
  {\text{Remember,}\Delta A = \text{change in}f\text{when}x} \\
  {\text{changes from}x = r\text{to}x = R\text{.}}
  \end{array}} \\
  {\phantom{\pi R^{2} - \pi r^{2}} \approx dA} \\
  {\phantom{\pi R^{2} - \pi r^{2}} = f^{\prime}(r)dr}
  \end{array}$$
